sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    // ==========================================================
    // VARIABLES
    // ==========================================================

    c.username = "";

    c.password = "";

    c.loading = false;

    c.errorMessage = "";


    // ==========================================================
    // LOGIN
    // ==========================================================

    c.login = function() {

        console.log("==========================================");
        console.log("CAMPUS LOGIN BUTTON CLICKED");
        console.log("==========================================");


        // ======================================================
        // CLEAR OLD ERROR
        // ======================================================

        c.errorMessage = "";


        // ======================================================
        // CHECK USERNAME
        // ======================================================

        if (!c.username) {

            console.log("LOGIN STOPPED: USERNAME IS EMPTY");

            c.errorMessage =
                "Please enter your username.";

            return;
        }


        // ======================================================
        // CHECK PASSWORD
        // ======================================================

        if (!c.password) {

            console.log("LOGIN STOPPED: PASSWORD IS EMPTY");

            c.errorMessage =
                "Please enter your password.";

            return;
        }


        // ======================================================
        // PRINT LOGIN DATA
        // ======================================================

        console.log("========== LOGIN DATA ==========");
        console.log("Username:", c.username);
        console.log("Password:", c.password);
        console.log("================================");


        // ======================================================
        // SHOW LOADING
        // ======================================================

        c.loading = true;

        console.log("LOGIN LOADING STARTED");


        // ======================================================
        // CREATE GLIDE AJAX
        // ======================================================

        console.log("Creating GlideAjax object...");

        var ga =
            new GlideAjax("x_snc_campus_foo_1.CampusLoginSessionUtils");

        console.log("GlideAjax object created successfully");


        // ======================================================
        // SCRIPT INCLUDE FUNCTION
        // ======================================================

        console.log("Sending sysparm_name = login");

        ga.addParam(
            "sysparm_name",
            "login"
        );


        // ======================================================
        // USERNAME
        // ======================================================

        console.log(
            "Sending username:",
            c.username
        );

        ga.addParam(
            "sysparm_username",
            c.username
        );


        // ======================================================
        // PASSWORD
        // ======================================================

        console.log(
            "Sending password:",
            c.password
        );

        ga.addParam(
            "sysparm_password",
            c.password
        );


        // ======================================================
        // CALL SCRIPT INCLUDE
        // ======================================================

        console.log("==========================================");
        console.log("CALLING SCRIPT INCLUDE...");
        console.log("Script Include: x_snc_campus_foo_1.CampusLoginSessionUtils");
        console.log("Function: login");
        console.log("Waiting for response...");
        console.log("==========================================");


        ga.getXMLAnswer(function(response) {

            console.log("==========================================");
            console.log("RESPONSE RECEIVED FROM SCRIPT INCLUDE");
            console.log("==========================================");

            console.log(
                "Raw Response:",
                response
            );


            // ==================================================
            // STOP LOADING
            // ==================================================

            c.loading = false;


            // ==================================================
            // NO RESPONSE
            // ==================================================

            if (!response) {

                console.log(
                    "ERROR: SCRIPT INCLUDE RETURNED NO RESPONSE"
                );

                c.errorMessage =
                    "Unable to connect to the login service.";

                $scope.$applyAsync();

                return;
            }


            // ==================================================
            // RESPONSE RECEIVED
            // ==================================================

            console.log(
                "Response is NOT empty."
            );


            // ==================================================
            // CONVERT RESPONSE TO OBJECT
            // ==================================================

            var result;


            try {

                console.log(
                    "Trying to parse JSON response..."
                );

                result =
                    JSON.parse(response);


                console.log(
                    "JSON PARSED SUCCESSFULLY"
                );

                console.log(
                    "Login Result Object:",
                    result
                );

            }

            catch (error) {

                console.log(
                    "JSON PARSE ERROR:",
                    error
                );

                c.errorMessage =
                    "Invalid response from login service.";

                $scope.$applyAsync();

                return;
            }


            // ==================================================
            // PRINT RECEIVED LOGIN DATA
            // ==================================================

            console.log("========== RECEIVED LOGIN DATA ==========");

            console.log(
                "Authentication:",
                result.authentication
            );

            console.log(
                "Session Number:",
                result.sessionNumber
            );

            console.log(
                "Session ID:",
                result.sessionId
            );

            console.log(
                "User Role:",
                result.userRole
            );

            console.log(
                "User Name:",
                result.userName
            );

            console.log(
                "User Sys ID:",
                result.user
            );

            console.log("=========================================");


            // ==================================================
            // CHECK AUTHENTICATION
            // ==================================================

            if (
                result.authentication === true
            ) {

                console.log(
                    "AUTHENTICATION SUCCESSFUL"
                );


                // ==============================================
                // CREATE LOGIN OBJECT
                // ==============================================

                var campusLogin = {

                    authentication:
                        result.authentication,

                    sessionNumber:
                        result.sessionNumber,

                    sessionId:
                        result.sessionId,

                    userRole:
                        result.userRole,

                    userName:
                        result.userName,

                    user:
                        result.user

                };


                console.log(
                    "Campus Login Object:",
                    campusLogin
                );


                // ==============================================
                // STORE IN LOCAL STORAGE
                // ==============================================

                localStorage.setItem(
                    "campusLogin",
                    JSON.stringify(campusLogin)
                );

                console.log(
                    "Campus Login Object stored in localStorage"
                );


                // ==============================================
                // ROLE BASED REDIRECTION
                // ==============================================

                if (
                    result.userRole === "Student"
                ) {

                    console.log(
                        "Redirecting to Student Dashboard"
                    );

                    $window.location.href ="https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_student_dashbaord_page";

                    return;
                }


                if (
                    result.userRole === "Staff"
                ) {

                    console.log(
                        "Redirecting to Staff Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_services_staff_dashboard_page";

                    return;
                }


                if (
                    result.userRole === "Admin"
                ) {

                    console.log(
                        "Redirecting to Admin Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_admin_dashboard_page";

                    return;
                }


                if (
                    result.userRole === "Manager"
                ) {

                    console.log(
                        "Redirecting to Manager Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_manager_dashboard_page";

                    return;
                }


                // ==============================================
                // UNKNOWN ROLE
                // ==============================================

                console.log(
                    "ERROR: UNKNOWN USER ROLE:",
                    result.userRole
                );

                c.errorMessage =
                    "No dashboard is configured for this role.";

                $scope.$applyAsync();

            }

            else {

                console.log(
                    "AUTHENTICATION FAILED"
                );

                console.log(
                    "Authentication value:",
                    result.authentication
                );


                // ==============================================
                // AUTHENTICATION FAILED
                // ==============================================

                c.errorMessage =
                    "Invalid username or user access.";

                $scope.$applyAsync();

            }

        });


        // ======================================================
        // IMPORTANT
        // ======================================================

        console.log(
            "GlideAjax request has been sent."
        );

        console.log(
            "NOW WAITING FOR SCRIPT INCLUDE RESPONSE..."
        );

    };


    // ==========================================================
    // ENTER KEY
    // ==========================================================

    c.checkEnter = function(event) {

        if (
            event.keyCode === 13
        ) {

            console.log(
                "ENTER KEY PRESSED - STARTING LOGIN"
            );

            c.login();

        }

    };

};

sp_widget.css:
/* =========================================================
   MEALCARE — LOGIN PAGE
   MATCHES MANAGER / STAFF / ADMIN DASHBOARD
   ServiceNow-safe CSS
   ========================================================= */


/* =========================================================
   PAGE BACKGROUND
   ========================================================= */

.cfa-login-page {
  position: relative;
  width: 100%;
  min-height: calc(100vh - 40px);

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 35px 40px;
  box-sizing: border-box;

  overflow: hidden;

  font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;

  background:
    radial-gradient(
      circle at 85% 15%,
      rgba(110, 217, 224, 0.30),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #F0FBFC 0%,
      #DDF7F9 50%,
      #C9F1F4 100%
    );
}


/* =========================================================
   DECORATIVE BACKGROUND
   ========================================================= */

.cfa-login-page::before {
  content: "";
  position: absolute;

  width: 420px;
  height: 420px;

  right: -180px;
  top: -160px;

  border-radius: 50%;

  background: rgba(110, 217, 224, 0.16);

  box-shadow:
    0 0 0 45px rgba(110, 217, 224, 0.06),
    0 0 0 90px rgba(110, 217, 224, 0.035);

  pointer-events: none;
}

.cfa-login-page::after {
  content: "";
  position: absolute;

  width: 300px;
  height: 300px;

  left: -170px;
  bottom: -150px;

  border-radius: 50%;

  background: rgba(6, 42, 51, 0.04);

  pointer-events: none;
}


/* =========================================================
   MAIN LOGIN CARD
   ========================================================= */

.cfa-login-card {
  position: relative;
  z-index: 2;

  width: 100%;
  max-width: 1050px;

  min-height: 600px;

  display: flex;

  overflow: hidden;

  background: #FFFFFF;

  border: 1px solid rgba(6, 42, 51, 0.08);

  border-radius: 26px;

  box-shadow:
    0 25px 60px rgba(6, 42, 51, 0.14),
    0 5px 20px rgba(6, 42, 51, 0.06);

  animation: loginCardEnter 0.55s ease-out both;
}


@keyframes loginCardEnter {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* =========================================================
   LEFT LOGIN FORM
   ========================================================= */

.cfa-login-form-section {
  width: 54%;

  padding: 48px 58px;

  box-sizing: border-box;

  display: flex;
  flex-direction: column;
  justify-content: center;

  background: #FFFFFF;
}


/* =========================================================
   BRAND
   ========================================================= */

.cfa-login-brand {
  display: flex;
  align-items: center;

  gap: 12px;

  margin-bottom: 42px;

  font-size: 22px;
  font-weight: 800;

  letter-spacing: -0.6px;

  color: #062A33;
}

.cfa-login-brand b {
  color: #0A4552;
}


/* LOGO */

.cfa-login-logo {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      #A2E8F3,
      #6ED9E0
    );

  color: #062A33;

  box-shadow:
    0 8px 20px rgba(110, 217, 224, 0.30);

  font-size: 21px;
}


/* =========================================================
   HEADING
   ========================================================= */

.cfa-login-heading h1 {
  margin: 0 0 8px;

  font-size: 34px;
  line-height: 1.15;

  font-weight: 800;

  letter-spacing: -1px;

  color: #062A33;
}

.cfa-login-heading p {
  margin: 0 0 30px;

  font-size: 15px;

  line-height: 1.6;

  color: #607A82;
}


/* =========================================================
   FORM
   ========================================================= */

.cfa-login-form {
  width: 100%;
}

.cfa-form-group {
  margin-bottom: 19px;
}


/* LABEL */

.cfa-form-group label {
  display: block;

  margin-bottom: 8px;

  font-size: 13px;

  font-weight: 800;

  color: #0A4552;
}


/* =========================================================
   INPUT
   ========================================================= */

.cfa-input-wrapper {
  position: relative;
}

.cfa-input-icon {
  position: absolute;

  left: 16px;
  top: 50%;

  transform: translateY(-50%);

  font-size: 16px;

  z-index: 2;
}


/* INPUT FIELD */

.cfa-input-wrapper input {
  width: 100%;
  height: 52px;

  padding: 0 16px 0 47px;

  box-sizing: border-box;

  border: 1px solid #BBD9DE;

  border-radius: 13px;

  background: #F5FBFC;

  color: #062A33;

  font-family: inherit;

  font-size: 14px;

  outline: none;

  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}


/* HOVER */

.cfa-input-wrapper input:hover {
  background: #EDF9FA;

  border-color: #91D7DE;
}


/* FOCUS */

.cfa-input-wrapper input:focus {
  background: #FFFFFF;

  border-color: #6ED9E0;

  box-shadow:
    0 0 0 4px rgba(110, 217, 224, 0.18);
}


/* PLACEHOLDER */

.cfa-input-wrapper input::placeholder {
  color: #8AA2A8;
}


/* AUTOFILL */

.cfa-input-wrapper input:-webkit-autofill,
.cfa-input-wrapper input:-webkit-autofill:hover,
.cfa-input-wrapper input:-webkit-autofill:focus {

  -webkit-box-shadow:
    0 0 0 1000px #F5FBFC inset !important;

  -webkit-text-fill-color: #062A33 !important;

  caret-color: #062A33;
}


/* =========================================================
   ERROR
   ========================================================= */

.cfa-login-error {
  margin-bottom: 18px;

  padding: 12px 14px;

  background: #FFF3F1;

  border: 1px solid #F3C5BF;

  border-radius: 11px;

  color: #B42318;

  font-size: 13px;

  font-weight: 600;
}


/* =========================================================
   LOGIN BUTTON
   ========================================================= */

.cfa-login-button {
  position: relative;

  width: 100%;
  height: 53px;

  border: none;

  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      #6ED9E0,
      #55C9D3
    );

  color: #062A33;

  font-family: inherit;

  font-size: 15px;

  font-weight: 800;

  cursor: pointer;

  overflow: hidden;

  box-shadow:
    0 10px 24px rgba(110, 217, 224, 0.28);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}


/* SHINE */

.cfa-login-button::before {
  content: "";

  position: absolute;

  top: 0;
  left: -120%;

  width: 70%;
  height: 100%;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,0.45),
      transparent
    );

  transform: skewX(-20deg);

  transition: left 0.55s ease;
}

.cfa-login-button:hover::before {
  left: 140%;
}


/* HOVER */

.cfa-login-button:hover {
  transform: translateY(-2px);

  box-shadow:
    0 15px 30px rgba(110, 217, 224, 0.36);

  background:
    linear-gradient(
      135deg,
      #7BE0E6,
      #5CCDD6
    );
}


/* ACTIVE */

.cfa-login-button:active {
  transform: translateY(0);
}


/* DISABLED */

.cfa-login-button:disabled {
  opacity: 0.6;

  cursor: not-allowed;

  transform: none;

  box-shadow: none;
}


/* =========================================================
   BACK HOME
   ========================================================= */

.cfa-back-home {
  margin-top: 24px;

  text-align: center;
}

.cfa-back-home a {
  color: #0A4552;

  font-size: 14px;

  font-weight: 700;

  text-decoration: none;

  transition: color 0.2s ease;
}

.cfa-back-home a:hover {
  color: #062A33;

  text-decoration: underline;
}


/* =========================================================
   RIGHT INFORMATION PANEL
   MATCHES MANAGER DASHBOARD HEADER
   ========================================================= */

.cfa-login-info {
  position: relative;

  width: 46%;

  padding: 50px;

  box-sizing: border-box;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  color: #FFFFFF;

  background:
    radial-gradient(
      circle at 88% 12%,
      rgba(110, 217, 224, 0.42),
      transparent 34%
    ),
    linear-gradient(
      rgba(162, 232, 243, 0.045) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(162, 232, 243, 0.045) 1px,
      transparent 1px
    ),
    linear-gradient(
      135deg,
      #062A33 0%,
      #0A4552 55%,
      #176574 100%
    );

  background-size:
    auto,
    32px 32px,
    32px 32px,
    auto;
}


/* =========================================================
   DECORATIVE CIRCLE
   ========================================================= */

.cfa-login-info::before {
  content: "";

  position: absolute;

  width: 310px;
  height: 310px;

  right: -150px;
  bottom: -140px;

  border-radius: 50%;

  border: 1px solid rgba(162, 232, 243, 0.30);

  box-shadow:
    0 0 0 35px rgba(162, 232, 243, 0.055),
    0 0 0 70px rgba(162, 232, 243, 0.035),
    0 0 0 105px rgba(162, 232, 243, 0.025);

  pointer-events: none;
}


/* TOP RIGHT GLOW */

.cfa-login-info::after {
  content: "";

  position: absolute;

  width: 260px;
  height: 260px;

  right: -110px;
  top: -140px;

  border-radius: 50%;

  background: rgba(110, 217, 224, 0.15);

  pointer-events: none;
}


/* =========================================================
   RIGHT CONTENT
   ========================================================= */

.cfa-login-info-content {
  position: relative;

  z-index: 3;

  width: 100%;

  max-width: 330px;

  text-align: center;
}


/* =========================================================
   FOOD ICON
   ========================================================= */

.cfa-food-icon {
  width: 92px;
  height: 92px;

  margin: 0 auto 25px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 26px;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,0.22),
      rgba(162,232,243,0.08)
    );

  border: 1px solid rgba(255,255,255,0.25);

  box-shadow:
    0 18px 40px rgba(0,0,0,0.20),
    inset 0 1px 0 rgba(255,255,255,0.28);

  font-size: 44px;

  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}


/* =========================================================
   RIGHT HEADING
   ========================================================= */

.cfa-login-info h2 {
  margin: 0 0 13px;

  font-size: 28px;

  line-height: 1.2;

  font-weight: 800;

  letter-spacing: -0.7px;

  color: #FFFFFF;
}


/* DESCRIPTION */

.cfa-login-info p {
  margin: 0;

  font-size: 14px;

  line-height: 1.7;

  color: rgba(255,255,255,0.80);
}


/* =========================================================
   FEATURES
   ========================================================= */

.cfa-login-features {
  margin-top: 30px;

  text-align: left;
}

.cfa-feature {
  display: flex;

  align-items: center;

  gap: 12px;

  margin-bottom: 13px;

  font-size: 14px;

  color: rgba(255,255,255,0.90);
}


/* FEATURE ICON */

.cfa-feature span:first-child {
  width: 27px;
  height: 27px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background:
    rgba(110,217,224,0.18);

  border:
    1px solid rgba(162,232,243,0.35);

  color: #A2E8F3;

  font-size: 13px;

  font-weight: 800;
}


/* =========================================================
   FOCUS ACCESSIBILITY
   ========================================================= */

.cfa-login-page a:focus-visible,
.cfa-login-page button:focus-visible,
.cfa-login-page input:focus-visible {

  outline: 3px solid #6ED9E0;

  outline-offset: 3px;

  border-radius: 8px;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

  .cfa-login-page {
    padding: 30px 25px;
  }

  .cfa-login-card {
    max-width: 760px;
  }

  .cfa-login-form-section {
    width: 55%;

    padding: 42px;
  }

  .cfa-login-info {
    width: 45%;

    padding: 35px;
  }

  .cfa-login-heading h1 {
    font-size: 31px;
  }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .cfa-login-page {
    min-height: calc(100vh - 20px);

    padding: 20px 15px;
  }

  .cfa-login-card {
    max-width: 500px;

    min-height: auto;

    border-radius: 22px;
  }

  .cfa-login-form-section {
    width: 100%;

    padding: 40px 30px;
  }

  .cfa-login-info {
    display: none;
  }

  .cfa-login-brand {
    margin-bottom: 35px;
  }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

  .cfa-login-page {
    padding: 12px;
  }

  .cfa-login-card {
    border-radius: 18px;
  }

  .cfa-login-form-section {
    padding: 32px 22px;
  }

  .cfa-login-heading h1 {
    font-size: 27px;
  }

  .cfa-login-heading p {
    font-size: 14px;
  }

  .cfa-login-brand {
    font-size: 20px;

    margin-bottom: 30px;
  }

  .cfa-login-logo {
    width: 42px;
    height: 42px;
  }

  .cfa-input-wrapper input {
    height: 50px;
  }

  .cfa-login-button {
    height: 50px;
  }
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfa-login-page *,
  .cfa-login-page *::before,
  .cfa-login-page *::after {

    animation: none !important;

    transition: none !important;
  }
}
